    let timer: ReturnType<typeof setTimeout> | null = null;
    return (...args: any[]) => {
        if (timer !== null) {
            clearTimeout(timer);
            timer = null;
            return;
        }
        const callFn = () => {
            timer = null;
            fn(args);
        };
        timer = setTimeout(callFn, waitMs);
    };
}
```

